'use strict';

/**
* Test whether a single-precision floating-point strided array contains at least `k` truthy elements.
*
* @module @stdlib/blas-ext-base-ssome
*
* @example
* import Float32Array from '@stdlib/array-float32';
* import ssome from '@stdlib/blas-ext-base-ssome';
*
* var x = new Float32Array( [ 0.0, 0.0, 1.0, 2.0 ] );
*
* var v = ssome( x.length, 2, x, 1 );
* // returns true
*
* @example
* import Float32Array from '@stdlib/array-float32';
* import ssome from '@stdlib/blas-ext-base-ssome';
*
* var x = new Float32Array( [ 0.0, 0.0, 1.0, 2.0 ] );
*
* var v = ssome.ndarray( x.length, 2, x, 1, 0 );
* // returns true
*/

// MODULES //

var join = require( 'path' ).join;
import tryRequire from '@stdlib/utils-try-require';
import isError from '@stdlib/assert-is-error';
import main from './main.js';


// MAIN //

var ssome;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	ssome = main;
} else {
	ssome = tmp;
}


// EXPORTS //

export default ssome;

// exports: { "ndarray": "ssome.ndarray" }
